const conn = msg.connection;
const base = global.get("pb").getBaseUrl("rayvn");

if (!conn || !conn.rayvn.api_key || !conn.rayvn.log_id) {
    node.error("Rayvn not configured on connection");
    return null;
}

msg.headers = {
    "Authorization": "Bearer " + conn.rayvn.api_key,
    "Content-Type": "application/json",
    "Accept": "application/json"
};

msg.url = base + "/logs/" + conn.rayvn.log_id + "/entry";

return msg;

msg.topic = "response"

if (msg.statusCode == 200) {
    msg.result = true
} else {
    msg.result = false
}

return msg;
